import {
  Mesh,
  PlaneGeometry,
  Group,
  Color
} from 'three/webgpu';
import {
  mix,
  fresnel,
  vec3,
  color
} from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  // Root container
  const container = new Group();

  // Geometry for the badge (aspect ratio from texture, default 1:1)
  const geometry = new PlaneGeometry(1, 1, 1, 1);
  geometry.rotateX(-Math.PI / 2); // make it face up (optional)

  // Base material with texture support
  const material = new MeshStandardNodeMaterial();
  material.color = new Color('#ffffff');
  material.metalness = 0.0;
  material.roughness = 0.8;
  material.clearcoat = 0.0;

  // Edge accent using Fresnel blend
  const accentColor = new Color('#ff2a38');
  material.emissiveNode = mix(
    vec3(0, 0, 0),
    color(accentColor),
    fresnel({ bias: 0.0, scale: 1.0, power: 2.0 })
  );
  material.emissiveIntensity = 0.5;

  // Mesh creation
  const mesh = new Mesh(geometry, material);
  container.add(mesh);

  // Load texture asynchronously
  let texturePromise = null;
  if (config.imageUrl) {
    texturePromise = ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        material.map = tex;
        material.needsUpdate = true;
        return tex;
      });
  }

  // Interaction state
  let hoverState = false;
  let hoverTimeline = null;
  const riseDistance = 0.15; // scene units

  // Handlers container
  const handlers = {};

  // Hover handler (toggle rise-in / settle)
  handlers.hover = () => {
    hoverState = !hoverState;
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    const targetY = hoverState ? mesh.position.y + riseDistance : mesh.position.y - riseDistance;
    hoverTimeline.to(
      mesh.position,
      {
        y: targetY,
        duration: 0.7,
        ease: 'power3.out'
      }
    );
  };

  // Click handler – emit selection event
  handlers.click = () => {
    ctx.emit('hub-collection.select', {});
  };

  // Attach handlers to userData
  container.userData.handlers = handlers;

  // Cleanup routine
  container.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();

    // Dispose texture if loaded
    if (texturePromise) {
      texturePromise.then((tex) => {
        tex.dispose();
      });
    }

    // Kill any GSAP timelines
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = null;
  };

  return container;
}
